"use client";
import React, { JSX, useState, useEffect, useCallback } from 'react';
import { useRouter, usePathname } from 'next/navigation';
import { useAuth } from '../../context/AuthContext';
import ErrorMessage from '../shared/ErrorMessage';
import { Eye, EyeOff, Mail, Phone, Lock, User, Github } from 'lucide-react';
import Link from 'next/link';
import { GoogleLogin } from '@react-oauth/google';
import { Button } from "@/app/components/ui/button";
import { Input } from "@/app/components/ui/input";
import { Label } from "@/app/components/ui/label";
import Image from "next/image";
import logo from "../../../public/logo.png";
import './auth-page.css';

interface AuthPageProps {
  initialMode: 'signIn' | 'signUp';
}

export default function AuthPage({ initialMode }: AuthPageProps): JSX.Element {
  const router = useRouter();
  const pathname = usePathname();
  const { login, register, loginWithGoogle, loginWithFacebook } = useAuth();
  
  const [isSignUp, setIsSignUp] = useState(initialMode === 'signUp');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  
  // Login State
  const [loginIdentifier, setLoginIdentifier] = useState('');
  const [loginPassword, setLoginPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);
  const [identifierWarning, setIdentifierWarning] = useState<string | null>(null);

  // SignUp State
  const [signUpData, setSignUpData] = useState({
    username: '',
    phone: '',
    password: '',
    email: ''
  });
  const [phoneWarning, setPhoneWarning] = useState<string | null>(null);
  const [emailWarning, setEmailWarning] = useState<string | null>(null);

  // Social Auth State
  const [fbReady, setFbReady] = useState(false);

  // Handle URL sync
  useEffect(() => {
    if (isSignUp && pathname !== '/signUp') {
      router.push('/signUp', { scroll: false });
    } else if (!isSignUp && pathname !== '/login') {
      router.push('/login', { scroll: false });
    }
  }, [isSignUp, pathname, router]);

  // Load saved identifier on mount
  useEffect(() => {
    const savedIdentifier = localStorage.getItem('rememberedIdentifier');
    const wasRemembered = localStorage.getItem('rememberMe') === 'true';

    if (wasRemembered && savedIdentifier) {
      setLoginIdentifier(savedIdentifier);
      setRememberMe(true);
    }
  }, []);

  // Validation Logics
  const validateIdentifier = (value: string) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\.]?[(]?[0-9]{1,4}[)]?[-\s\.]?[0-9]{1,9}$/;

    if (value && !emailRegex.test(value) && !phoneRegex.test(value)) {
      setIdentifierWarning('Please enter a valid email or phone number');
    } else {
      setIdentifierWarning(null);
    }
  };

  const validatePhone = (value: string) => {
    const phoneRegex = /^[\+]?[(]?[0-9]{1,4}[)]?[-\s\.]?[(]?[0-9]{1,4}[)]?[-\s\.]?[0-9]{1,9}$/;
    if (value && !phoneRegex.test(value)) {
      setPhoneWarning('Please enter a valid phone number');
    } else {
      setPhoneWarning(null);
    }
  };

  const validateEmail = (value: string) => {
    if (!value) {
      setEmailWarning(null);
      return;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      setEmailWarning('Please enter a valid email address');
    } else {
      setEmailWarning(null);
    }
  };

  // Handlers
  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);

    if (!loginIdentifier || !loginPassword) {
      setError('Please fill in all fields');
      return;
    }

    setLoading(true);
    try {
      const result = await login(loginIdentifier, loginPassword);
      if (result.success) {
        if (result.verificationRequired) {
          setSuccessMessage(result.message || 'Verification required. Redirecting...');
          setTimeout(() => {
            const emailParam = result.email ? `?email=${encodeURIComponent(result.email)}` : '';
            router.push(`/verify-email${emailParam}`);
          }, 1500);
          return;
        }

        if (rememberMe) {
          localStorage.setItem('rememberedIdentifier', loginIdentifier);
          localStorage.setItem('rememberMe', 'true');
        } else {
          localStorage.removeItem('rememberedIdentifier');
          localStorage.removeItem('rememberMe');
        }

        setSuccessMessage('Login successful! Redirecting...');
        setTimeout(() => router.push('/'), 1000);
      } else {
        setError(result.error || 'Login failed');
      }
    } catch (err: any) {
      setError(err?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSignUpSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSuccessMessage(null);

    if (!signUpData.username || !signUpData.phone || !signUpData.password) {
      setError('Please fill in all required fields');
      return;
    }

    if (signUpData.password.length < 8) {
      setError('Password must be at least 8 characters long');
      return;
    }

    setLoading(true);
    try {
      const result = await register(
        signUpData.username,
        signUpData.phone,
        signUpData.password,
        signUpData.email || undefined
      );

      if (result.success) {
        setSuccessMessage('Account created successfully! Redirecting...');
        setTimeout(() => router.push('/'), 1500);
      } else {
        setError(result.error || 'Registration failed');
      }
    } catch (err: any) {
      setError(err?.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSocialSuccess = async (credentialResponse: any, isReg: boolean) => {
    setLoading(true);
    setError(null);
    try {
      const result = await loginWithGoogle(credentialResponse.credential, false);
      if (result.success) {
        setSuccessMessage('Auth successful! Redirecting...');
        setTimeout(() => router.push('/'), 1000);
      } else {
        setError(result.error || 'Social auth failed');
      }
    } catch (err: any) {
      setError(err?.message || 'Social auth failed');
    } finally {
      setLoading(false);
    }
  };

  // Facebook SDK Logic
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const fbAppId = process.env.NEXT_PUBLIC_FACEBOOK_APP_ID;
      if (!fbAppId || fbAppId === 'your_facebook_app_id_here') return;

      (window as any).fbAsyncInit = function () {
        (window as any).FB.init({
          appId: fbAppId,
          cookie: true,
          xfbml: true,
          version: 'v18.0'
        });
        setFbReady(true);
      };

      (function (d, s, id) {
        var js: any, fjs: any = d.getElementsByTagName(s)[0];
        if (d.getElementById(id)) return;
        js = d.createElement(s); js.id = id;
        js.src = "https://connect.facebook.net/en_US/sdk.js";
        fjs.parentNode.insertBefore(js, fjs);
      }(document, 'script', 'facebook-jssdk'));
    }
  }, []);

  const handleFacebookLogin = () => {
    if (!fbReady) {
      setError('Facebook SDK is still loading...');
      return;
    }

    (window as any).FB.login((response: any) => {
      if (response.authResponse) {
        setLoading(true);
        loginWithFacebook(response.authResponse.accessToken, response.authResponse.userID)
          .then((result) => {
            if (result.success) {
              setSuccessMessage('Login successful! Redirecting...');
              setTimeout(() => router.push('/'), 1000);
            } else {
              setError(result.error || 'Facebook login failed');
            }
          })
          .catch((err) => setError(err?.message || 'Facebook login failed'))
          .finally(() => setLoading(false));
      }
    }, { scope: 'public_profile' });
  };

  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-br from-background via-muted/20 to-background">
      <header className="p-4 md:p-6">
        <Link href="/" className="flex items-center gap-2 max-w-max">
          <Image src={logo} alt="Dosro Bazar" width={140} height={45} className="h-10 w-auto cursor-pointer" />
        </Link>
      </header>

      <main className="flex-1 flex items-center justify-center p-4">
        <div className={`auth-container ${isSignUp ? 'right-panel-active' : ''}`} id="auth-container">
          
          {/* Sign Up Form */}
          <div className={`form-container sign-up-container ${isSignUp ? 'active' : ''}`}>
            <form onSubmit={handleSignUpSubmit} className="auth-form">
              <h1 className="text-3xl font-bold mb-2">Create Account</h1>
              <Button disabled={loading} type="submit" className="mt-6 w-full h-12 rounded-full font-bold uppercase tracking-wider transition-all hover:scale-105 active:scale-95 shadow-lg shadow-primary/20">
                {loading ? 'Creating...' : 'Sign Up'}
              </Button>

              <div className="w-full mt-6">
                <div className="relative mb-4">
                  <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-muted" /></div>
                  <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-muted-foreground">Or continue with</span></div>
                </div>
                <div className="flex gap-4 justify-center items-center">
                  <button type="button" onClick={() => handleFacebookLogin()} className="social-icon-btn facebook-btn" title="Sign up with Facebook">
                    <svg className="w-5 h-5 text-[#1877F2]" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
                    </svg>
                  </button>
                  <div className="social-login-wrapper">
                    <GoogleLogin onSuccess={(res) => handleSocialSuccess(res, true)} onError={() => setError('Google failed')} />
                  </div>
                </div>
              </div>
              
              <p className="mobile-toggle" onClick={() => setIsSignUp(false)}>Already a user? Sign In</p>
              
              <p className="mobile-toggle" onClick={() => setIsSignUp(false)}>Already a user? Sign In</p>
            </form>
          </div>

          {/* Sign In Form */}
          <div className={`form-container sign-in-container ${!isSignUp ? 'active' : ''}`}>
            <form onSubmit={handleLoginSubmit} className="auth-form">
              <h1 className="text-3xl font-bold mb-2">Sign In</h1>
              <Button disabled={loading} type="submit" className="mt-6 w-full h-12 rounded-full font-bold uppercase tracking-wider transition-all hover:scale-105 active:scale-95 shadow-lg shadow-primary/20">
                {loading ? 'Signing In...' : 'Sign In'}
              </Button>

              <div className="w-full mt-6">
                <div className="relative mb-4">
                  <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-muted" /></div>
                  <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-muted-foreground">Or continue with</span></div>
                </div>
                <div className="flex gap-4 justify-center items-center">
                  <button type="button" onClick={() => handleFacebookLogin()} className="social-icon-btn facebook-btn" title="Sign in with Facebook">
                    <svg className="w-5 h-5 text-[#1877F2]" fill="currentColor" viewBox="0 0 24 24">
                      <path d="M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z" />
                    </svg>
                  </button>
                  <div className="social-login-wrapper">
                    <GoogleLogin onSuccess={(res) => handleSocialSuccess(res, false)} onError={() => setError('Google failed')} />
                  </div>
                </div>
              </div>
              
              <p className="mobile-toggle" onClick={() => setIsSignUp(true)}>New here? Create Account</p>
              
              <p className="mobile-toggle" onClick={() => setIsSignUp(true)}>New here? Create Account</p>
            </form>
          </div>

          {/* Overlay Container */}
          <div className="overlay-container">
            <div className="overlay">
              <div className="overlay-panel overlay-left">
                <h1 className="text-4xl font-extrabold mb-4">Welcome Buddy!</h1>
                <p className="text-lg mb-8 opacity-90">Already have an account? Keep in touch with us by logging in with your personal info</p>
                <Button variant="outline" className="rounded-full border-2 border-white bg-transparent hover:bg-white/10 text-white w-48 h-12 font-bold uppercase" onClick={() => setIsSignUp(false)}>
                  Sign In
                </Button>
              </div>
              <div className="overlay-panel overlay-right">
                <h1 className="text-4xl font-extrabold mb-4">Namaste, Friend!</h1>
                <p className="text-lg mb-8 opacity-90">Enter your personal details and start your journey with Dosro Bazar today</p>
                <Button variant="outline" className="rounded-full border-2 border-white bg-transparent hover:bg-white/10 text-white w-48 h-12 font-bold uppercase" onClick={() => setIsSignUp(true)}>
                  Sign Up
                </Button>
              </div>
            </div>
          </div>

        </div>
      </main>

      <footer className="p-6 text-center text-sm text-muted-foreground">
        © {new Date().getFullYear()} Dosro Bazar. All rights reserved.
      </footer>

      <style jsx>{`
        .social-icon-btn {
          width: 40px;
          height: 40px;
          border-radius: 50%;
          border: 1px solid #ddd;
          display: flex;
          align-items: center;
          justify-content: center;
          transition: all 0.3s ease;
        }
        .social-icon-btn:hover {
          background-color: #f5f5f5;
          transform: translateY(-2px);
        }
        .social-login-wrapper {
          overflow: hidden;
          border-radius: 4px;
        }
      `}</style>
    </div>
  );
}
